-- SALST V11: run on a NEW PostgreSQL database before importing CSV data.
-- The backend init() also performs idempotent additive migrations for V10 databases.
CREATE TABLE IF NOT EXISTS owners(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,pw TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'owner',farm_owner BIGINT REFERENCES owners(id),can_reset_alarm BOOLEAN NOT NULL DEFAULT FALSE,time_format TEXT NOT NULL DEFAULT '24h',farm_name TEXT NOT NULL DEFAULT '',alarm_enabled BOOLEAN NOT NULL DEFAULT TRUE,lost_warning_seconds INTEGER NOT NULL DEFAULT 120);
CREATE TABLE IF NOT EXISTS tags(id TEXT PRIMARY KEY,owner BIGINT NOT NULL REFERENCES owners(id),name TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'peace',last_seen TEXT,lat DOUBLE PRECISION,lon DOUBLE PRECISION,battery DOUBLE PRECISION DEFAULT 100,seq BIGINT DEFAULT 0,peace_sec INTEGER DEFAULT 30,emergency_sec INTEGER DEFAULT 5,charging INTEGER DEFAULT 1,device_number BIGINT GENERATED BY DEFAULT AS IDENTITY,animal_number TEXT,hardware_mac TEXT UNIQUE,claim_hash TEXT,device_secret_hash TEXT,lost_contact BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS reports(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tag TEXT REFERENCES tags(id),seq BIGINT NOT NULL,stamp TEXT NOT NULL,lat DOUBLE PRECISION,lon DOUBLE PRECISION,battery DOUBLE PRECISION,mode TEXT,UNIQUE(tag,seq));
CREATE TABLE IF NOT EXISTS events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tag TEXT REFERENCES tags(id),stamp TEXT NOT NULL,kind TEXT NOT NULL,message TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS geofences(owner BIGINT PRIMARY KEY REFERENCES owners(id),shape TEXT DEFAULT 'circle',lat DOUBLE PRECISION DEFAULT -25.7479,lon DOUBLE PRECISION DEFAULT 28.2293,radius DOUBLE PRECISION DEFAULT 10,north DOUBLE PRECISION DEFAULT -25.744,south DOUBLE PRECISION DEFAULT -25.752,east DOUBLE PRECISION DEFAULT 28.234,west DOUBLE PRECISION DEFAULT 28.225,configured BOOLEAN NOT NULL DEFAULT FALSE,gateway_lat DOUBLE PRECISION,gateway_lon DOUBLE PRECISION,coverage_radius DOUBLE PRECISION NOT NULL DEFAULT 2000,show_coverage BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS commands(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tag TEXT REFERENCES tags(id),kind TEXT,created TEXT,applied TEXT);
CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,owner BIGINT NOT NULL REFERENCES owners(id),tag TEXT REFERENCES tags(id),stamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),title TEXT NOT NULL,body TEXT NOT NULL,read BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS push_subscriptions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor BIGINT NOT NULL REFERENCES owners(id),endpoint TEXT UNIQUE NOT NULL,subscription JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS simulator_control(tag TEXT PRIMARY KEY REFERENCES tags(id) ON DELETE CASCADE,instruction JSONB NOT NULL DEFAULT '{}'::jsonb,revision BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS emergencies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tag TEXT NOT NULL REFERENCES tags(id),started TIMESTAMPTZ NOT NULL DEFAULT NOW(),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',acknowledged_at TIMESTAMPTZ,acknowledged_by BIGINT REFERENCES owners(id) ON DELETE SET NULL,resolved_at TIMESTAMPTZ,resolved_by BIGINT REFERENCES owners(id) ON DELETE SET NULL,resolution TEXT,last_lat DOUBLE PRECISION,last_lon DOUBLE PRECISION,last_seen TEXT);
CREATE TABLE IF NOT EXISTS lost_tags(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,emergency_id BIGINT UNIQUE NOT NULL REFERENCES emergencies(id),tag TEXT NOT NULL REFERENCES tags(id),classified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),classified_by BIGINT REFERENCES owners(id) ON DELETE SET NULL,classification TEXT NOT NULL,last_seen TEXT,last_lat DOUBLE PRECISION,last_lon DOUBLE PRECISION,notes TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS idx_emergencies_active ON emergencies(tag) WHERE status IN ('active','lost');
CREATE INDEX IF NOT EXISTS idx_reports_tag_stamp ON reports(tag,stamp DESC);
CREATE INDEX IF NOT EXISTS idx_emergencies_tag ON emergencies(tag,started DESC);
